const menuToggle = document.querySelector('.menu-toggle');
const mainNav = document.querySelector('.main-nav');
const toast = document.querySelector('.toast');
const gameGrid = document.querySelector('#game-grid');
const introScreen = document.querySelector('[data-intro]');
const enterSite = document.querySelector('[data-enter-site]');
const loadingCovers = [304240,883710,2050650,1245620,1091500,1086940,2124490,1174180,1593500,367520,1145360,782330];

function enterArchive() {
  if (!introScreen) return;
  introScreen.classList.add('intro-hidden');
  document.body.classList.remove('intro-active');
  window.setTimeout(() => introScreen.remove(), 700);
}

if (introScreen) {
  document.body.classList.add('intro-active');
  introScreen.querySelector('.intro-grid').innerHTML = loadingCovers.map((appId) => `<img src="https://shared.fastly.steamstatic.com/store_item_assets/steam/apps/${appId}/library_600x900_2x.jpg" alt="" loading="eager">`).join('');
  enterSite.addEventListener('click', enterArchive);
  document.addEventListener('keydown', (event) => {
    if (event.key === 'Enter' && document.body.contains(introScreen)) enterArchive();
  });
}
let selectedEra = 'all';
let selectedCategory = 'all';

function createLoader(type = 'all') {
  const loader = document.createElement('div');
  loader.className = `site-loader ${type === 'resident' ? 'resident-loader' : 'all-games-loader'}`;
  const coverTiles = loadingCovers.map((appId) => `<img src="https://shared.fastly.steamstatic.com/store_item_assets/steam/apps/${appId}/library_600x900_2x.jpg" alt="" loading="eager">`).join('');
  loader.innerHTML = type === 'resident'
    ? '<div class="umbrella-mark"><span>☂</span><small>UMBRELLA</small></div><p class="loader-kicker">ARQUIVO NOX / DOSSIÊ RESIDENT EVIL</p><strong>Carregando<br><em>Raccoon City.</em></strong><div class="loader-line"><i></i></div>'
    : `<div class="loader-collage">${coverTiles}</div><p class="loader-kicker">ARQUIVO NOX / GAME ARCHIVE</p><strong>Reunindo<br><em>todas as histórias.</em></strong><div class="loader-line"><i></i></div>`;
  document.body.append(loader);
  return loader;
}

function playLoader(type = 'all', duration = 900) {
  const loader = createLoader(type);
  window.setTimeout(() => {
    loader.classList.add('loader-hidden');
    window.setTimeout(() => loader.remove(), 500);
  }, duration);
}

if (!sessionStorage.getItem('nox-loaded')) {
  sessionStorage.setItem('nox-loaded', 'true');
  playLoader();
}

document.querySelectorAll('a[href*="resident-evil"]').forEach((link) => {
  link.addEventListener('click', (event) => {
    event.preventDefault();
    const destination = link.href;
    playLoader('resident', 1050);
    window.setTimeout(() => { window.location.href = destination; }, 1050);
  });
});

const loaderStyle = document.createElement('style');
loaderStyle.textContent = '.site-loader{align-items:center;background:var(--ink);color:var(--paper);display:flex;flex-direction:column;inset:0;justify-content:center;overflow:hidden;position:fixed;z-index:20}.all-games-loader{background:var(--paper);color:var(--ink)}.loader-collage{display:flex;height:190px;justify-content:center;margin-bottom:36px;overflow:hidden;transform:rotate(-5deg);width:100%}.loader-collage img{height:190px;object-fit:cover;opacity:.82;width:100px}.loader-collage img:nth-child(odd){margin-top:18px}.loader-kicker{color:var(--red);font-family:var(--mono);font-size:10px;letter-spacing:.1em;margin:0 0 22px;text-transform:uppercase}.site-loader strong{font-size:clamp(42px,7vw,82px);letter-spacing:-.09em;line-height:.8;text-align:center}.site-loader em{color:var(--red);font-style:normal}.loader-line{background:rgba(240,237,230,.25);height:1px;margin-top:40px;overflow:hidden;width:180px}.all-games-loader .loader-line{background:rgba(23,23,22,.2)}.loader-line i{animation:loader-progress 1s ease-in-out forwards;background:var(--red);display:block;height:100%;transform-origin:left;width:100%}.umbrella-mark{align-items:center;border:1px solid var(--red);border-radius:50%;display:flex;flex-direction:column;height:150px;justify-content:center;margin-bottom:34px;width:150px}.umbrella-mark span{color:var(--red);font-size:75px;line-height:.8}.umbrella-mark small{color:var(--red);font-family:var(--mono);font-size:9px;letter-spacing:.12em;margin-top:8px}.resident-loader .loader-kicker{color:#d7ad43}.resident-loader .loader-line i{background:#d7ad43}.resident-loader strong em{color:#d7ad43}.loader-hidden{opacity:0;transition:opacity .5s}@keyframes loader-progress{from{transform:scaleX(0)}to{transform:scaleX(1)}}@media(max-width:760px){.loader-collage{height:140px}.loader-collage img{height:140px;width:65px}.umbrella-mark{height:125px;width:125px}.umbrella-mark span{font-size:60px}}';
document.head.append(loaderStyle);
