extraTitles.forEach((title, index) => {
  if (!catalog.some(([existingTitle]) => existingTitle === title)) {
    const year = 2010 + (index % 16);
    catalog.push([title, year, 'Jogo em destaque', null, `A história de ${title} acompanha personagens marcantes em uma jornada de descoberta, conflito e transformação. O mundo do jogo apresenta desafios, escolhas e segredos para explorar em diferentes momentos da campanha.`]);
  }
});
const uniqueCatalog = [...new Map(catalog.map((game) => [game[0], game])).values()];

function renderCatalog() {
  if (!gameGrid) return;
  gameGrid.innerHTML = uniqueCatalog.map(([title, year, genre, appId, story], index) => {
    const era = index < 4 ? 'classic' : index < 12 ? 'spin' : 'modern';
    const cover = appId ? `https://shared.fastly.steamstatic.com/store_item_assets/steam/apps/${appId}/library_600x900_2x.jpg` : '';
    const coverMarkup = cover ? `<img src="${cover}" alt="Capa oficial de ${title}" loading="lazy" onerror="this.parentElement.classList.add('cover-unavailable');this.remove()">` : '<div class="cover-unavailable-label">Capa oficial<br>em pesquisa</div>';
    const category = genre.toLocaleLowerCase('pt-BR').match(/horror|terror/) ? 'horror' : genre.toLocaleLowerCase('pt-BR').match(/rpg|roguelike|metroidvania/) ? 'rpg' : genre.toLocaleLowerCase('pt-BR').match(/ação|tiro|luta|stealth/) ? 'acao' : genre.toLocaleLowerCase('pt-BR').match(/aventura|exploração|plataforma|narrativa/) ? 'aventura' : genre.toLocaleLowerCase('pt-BR').match(/estratégia|moba/) ? 'estrategia' : genre.toLocaleLowerCase('pt-BR').match(/simulação|esporte/) ? 'simulacao' : genre.toLocaleLowerCase('pt-BR').match(/cooperação|multiplayer|competitivo|social/) ? 'multiplayer' : 'aventura';
    return `<article class="game-card reveal" data-era="${era}" data-category="${category}"><div class="game-cover official-cover">${coverMarkup}<span>${year}</span></div><div class="game-info"><p class="card-type">${genre}</p><h3>${title}</h3><p>${story}</p><button class="read-button" data-story="${title}">Ler a história <span>↗</span></button></div></article>`;
  }).join('');
  document.querySelectorAll('.game-card.reveal').forEach((element) => observer.observe(element));
}

menuToggle.addEventListener('click', () => {
  const isOpen = mainNav.classList.toggle('open');
  menuToggle.setAttribute('aria-expanded', String(isOpen));
});

document.querySelectorAll('.main-nav a').forEach((link) => {
  link.addEventListener('click', () => {
    mainNav.classList.remove('open');
    menuToggle.setAttribute('aria-expanded', 'false');
  });
});

const observer = new IntersectionObserver((entries) => {
  entries.forEach((entry) => {
    if (entry.isIntersecting) entry.target.classList.add('visible');
  });
}, { threshold: 0.12 });

document.querySelectorAll('.reveal').forEach((element) => observer.observe(element));
renderCatalog();

function applyFilters() {
  const currentSearchInput = document.querySelector('[data-search-input]');
  const query = currentSearchInput?.value.trim().toLocaleLowerCase('pt-BR') || '';
  let matches = 0;
  document.querySelectorAll('.game-card').forEach((card) => {
    const searchableText = card.textContent.toLocaleLowerCase('pt-BR');
    const isMatch = (selectedEra === 'all' || card.dataset.era === selectedEra) && (selectedCategory === 'all' || card.dataset.category === selectedCategory) && (!query || searchableText.includes(query));
    card.classList.toggle('hidden', !isMatch);
    if (isMatch) matches += 1;
  });
  const resultMessage = document.querySelector('.search-result');
  if (resultMessage && query) resultMessage.textContent = `${matches} jogo${matches === 1 ? '' : 's'} encontrado${matches === 1 ? '' : 's'} para “${searchInput.value}”.`;
}

document.querySelectorAll('.filter').forEach((filterButton) => {
  filterButton.addEventListener('click', () => {
    document.querySelectorAll('.filter').forEach((button) => button.classList.remove('active'));
    filterButton.classList.add('active');
    selectedEra = filterButton.dataset.filter;
    applyFilters();
  });
});

document.querySelectorAll('.category').forEach((categoryButton) => {
  categoryButton.addEventListener('click', () => {
    document.querySelectorAll('.category').forEach((button) => button.classList.remove('active'));
    categoryButton.classList.add('active');
    selectedCategory = categoryButton.dataset.category;
    applyFilters();
  });
});

document.querySelectorAll('.read-button').forEach((button) => {
  button.addEventListener('click', () => {
    const card = button.closest('.game-card');
    const title = button.dataset.story;
    if (title.startsWith('Resident Evil') && button.dataset.loaderReady !== 'true') {
      button.dataset.loaderReady = 'true';
      playLoader('resident', 1050);
      window.setTimeout(() => button.click(), 1050);
      return;
    }
    button.dataset.loaderReady = 'false';
    const year = card?.querySelector('.game-cover span')?.textContent || 'Arquivo Nox';
    const genre = card?.querySelector('.card-type')?.textContent || 'Videogame';
    const shortStory = card?.querySelector('.game-info > p:not(.card-type)')?.textContent || 'História em pesquisa no arquivo.';
    const story = expandedStories[title] || `${shortStory} ${title} apresenta uma jornada construída em torno de personagens, conflitos e descobertas. Ao avançar, o jogador encontra pistas no cenário, diálogos e acontecimentos que ampliam o significado da campanha. A experiência combina progressão, exploração e decisões que ajudam a definir o ritmo da aventura.\n\nO mundo de ${title} recompensa a atenção aos detalhes. Objetivos opcionais, encontros e documentos revelam informações além da missão principal e tornam cada partida uma leitura diferente do universo. A história cresce quando o jogador conecta esses fragmentos e percebe como suas escolhas afetam o caminho até o final.`;
    let dossier = document.querySelector('.dossier-modal');
    if (!dossier) {
      if (!document.querySelector('#dossier-style')) {
        const dossierStyle = document.createElement('style');
        dossierStyle.id = 'dossier-style';
        dossierStyle.textContent = '.dossier-modal{align-items:center;background:rgba(23,23,22,.78);display:flex;inset:0;justify-content:center;padding:20px;position:fixed;z-index:10}.dossier-modal[hidden]{display:none}.dossier-panel{background:var(--paper);max-height:90vh;max-width:700px;overflow:auto;padding:45px;position:relative;width:100%}.dossier-close{background:none;border:0;cursor:pointer;font-size:28px;position:absolute;right:18px;top:13px}.dossier-panel h2{font-size:clamp(40px,6vw,70px);letter-spacing:-.09em;line-height:.85;margin:24px 0}.dossier-panel h3{font-family:var(--mono);font-size:10px;letter-spacing:.08em;margin:28px 0 9px;text-transform:uppercase}.dossier-meta{color:var(--red);font-family:var(--mono);font-size:11px;letter-spacing:.08em;text-transform:uppercase}.dossier-title-copy{color:var(--red);font-weight:600}.dossier-story,.dossier-lore,.dossier-mechanics,.dossier-platforms,.dossier-trivia{font-size:17px;line-height:1.7;margin:0 0 20px;white-space:pre-line}.dossier-note{border-top:1px solid rgba(23,23,22,.25);color:var(--muted);font-family:var(--mono);font-size:10px;line-height:1.5;padding-top:17px}@media(max-width:760px){.dossier-panel{padding:35px 25px}.dossier-story,.dossier-lore,.dossier-mechanics,.dossier-platforms,.dossier-trivia{font-size:16px}}';
        document.head.append(dossierStyle);
      }
      dossier = document.createElement('div');
      dossier.className = 'dossier-modal';
      dossier.innerHTML = '<div class="dossier-panel" role="dialog" aria-modal="true" aria-labelledby="dossier-title"><button class="dossier-close" type="button" aria-label="Fechar dossiê">×</button><p class="eyebrow">Dossiê Nox / ficha completa</p><h2 id="dossier-title"></h2><div class="dossier-meta"></div><h3>Título</h3><p class="dossier-title-copy"></p><h3>História</h3><p class="dossier-story"></p><h3>Lore</h3><p class="dossier-lore"></p><h3>Mecânicas</h3><p class="dossier-mechanics"></p><h3>Plataformas</h3><p class="dossier-platforms"></p><h3>Curiosidade</h3><p class="dossier-trivia"></p><p class="dossier-note">As plataformas listadas são as versões mais conhecidas e podem variar por edição.</p></div></div>';
      document.body.append(dossier);
      dossier.querySelector('.dossier-close').addEventListener('click', () => { dossier.hidden = true; });
      dossier.addEventListener('click', (event) => { if (event.target === dossier) dossier.hidden = true; });
    }
    dossier.querySelector('#dossier-title').textContent = title;
    dossier.querySelector('.dossier-meta').textContent = `${year}  /  ${genre}`;
    const facts = gameFacts[title] || ['PC e consoles', 'Exploração, progressão e sistemas próprios do gênero.', 'Cada jogo guarda detalhes de produção e referências que ampliam sua leitura.'];
    dossier.querySelector('.dossier-title-copy').textContent = title;
    dossier.querySelector('.dossier-story').textContent = story;
    dossier.querySelector('.dossier-lore').textContent = lore[title] || `O universo de ${title} é construído por seus personagens, conflitos e regras próprias. Este registro reúne o ponto de partida da história para orientar a leitura do jogo.`;
    dossier.querySelector('.dossier-mechanics').textContent = facts[1];
    dossier.querySelector('.dossier-platforms').textContent = facts[0];
    dossier.querySelector('.dossier-trivia').textContent = facts[2];
    dossier.hidden = false;
  });
});

const searchForm = document.querySelector('[data-search-form]');
const searchInput = document.querySelector('[data-search-input]');

if (searchForm && searchInput) {
  const searchGames = () => {
    const query = searchInput.value.trim().toLocaleLowerCase('pt-BR');
    let matches = 0;
    document.querySelectorAll('.game-card').forEach((card) => {
      const searchableText = card.textContent.toLocaleLowerCase('pt-BR');
      const isMatch = !query || searchableText.includes(query);
      if (isMatch) matches += 1;
    });
    const archive = document.querySelector('.archive');
    let resultMessage = document.querySelector('.search-result');
    if (!resultMessage) {
      resultMessage = document.createElement('p');
      resultMessage.className = 'search-result';
      archive.querySelector('.filter-bar').after(resultMessage);
    }
    applyFilters();
    resultMessage.textContent = query ? `${document.querySelectorAll('.game-card:not(.hidden)').length} jogo${matches === 1 ? '' : 's'} encontrado${matches === 1 ? '' : 's'} para “${searchInput.value}”.` : '';
  };
  searchForm.addEventListener('submit', (event) => { event.preventDefault(); searchGames(); });
  searchInput.addEventListener('input', searchGames);
}